        if (n == 1) {
            System.out.println(1);
            return;
        }

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int i = 0; i < n - 1; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            int u = Integer.parseInt(parts[0]) - 1;
            int v = Integer.parseInt(parts[1]) - 1;
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        // dp[v][0] = number of ways for subtree rooted at v such that v is NOT matched to any child
        // dp[v][1] = number of ways for subtree rooted at v such that v IS matched to exactly one child
        // We need to track:
        // - The maximum matching size
        // - The number of ways to achieve that maximum matching with unique maximum matching

        // Let's define:
        // dp0[v] = (max_matching_size, count) for subtree v where v is free (not matched to parent)
        //   and the maximum matching in the subtree is unique
        // dp1[v] = (max_matching_size, count) for subtree v where v is matched to one of its children
        //   and the maximum matching in the subtree is unique

        // Actually, let's think differently.
