        //   We need to find the maximum over all choices of which child u to match with.

        long[][] f0 = new long[n][2]; // f0[v][0] = size, f0[v][1] = count
        long[][] f1 = new long[n][2]; // f1[v][0] = size, f1[v][1] = count

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] order = new int[n];
        int[] depth = new int[n];

        // BFS to get order
        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);
        parent[0] = -1;
        int idx = 0;
        while (!queue.isEmpty()) {
            int v = queue.poll();
            order[idx++] = v;
            for (int u : adj.get(v)) {
                if (u == parent[v]) continue;
                parent[u] = v;
                depth[u] = depth[v] + 1;
                queue.add(u);
