            //   size = 1 + f[u][0].size + sum_{w != u} max(f[w][0].size, f[w][1].size)

            // Let's precompute for each child the best size and count
            List<Integer> children = new ArrayList<>();
            for (int u : adj.get(v)) {
                if (u == parent[v]) continue;
                children.add(u);
            }

            // For each child, compute best size and whether it's unique
            long[] childBestSize = new long[children.size()];
            long[] childBestCount = new long[children.size()];
            boolean[] childUnique = new boolean[children.size()];

            for (int j = 0; j < children.size(); j++) {
                int u = children.get(j);
                long s0 = f0[u][0];
                long c0 = f0[u][1];
                long s1 = f1[u][0];
                long c1 = f1[u][1];

                if (s0 > s1) {
                    childBestSize[j] = s0;
                    childBestCount[j] = c0;
                    childUnique[j] = true;
                } else if (s1 > s0) {
                    childBestSize[j] = s1;
                    childBestCount[j] = c1;
                    childUnique[j] = true;
                } else {
                    childBestSize[j] = s0;
                    childBestCount[j] = (c0 + c1) % MOD;
                    childUnique[j] = false;
                }

                baseSize += childBestSize[j];
                baseCount = (baseCount * childBestCount[j]) % MOD;
                if (!childUnique[j]) {
                    baseUnique = false;
                }
            }

            // f[v][0]
            f0[v][0] = baseSize;
            f0[v][1] = baseCount;

            // f[v][1]: try matching v with each child
            // For child j, size = 1 + f0[children.get(j)][0] + (baseSize - childBestSize[j])
            // We need the maximum such size, and count the number of ways.

            long maxMatchSize = -1;
            long totalWays = 0;

            for (int j = 0; j < children.size(); j++) {
                int u = children.get(j);
                long matchSize = 1 + f0[u][0] + (baseSize - childBestSize[j]);

                if (matchSize > maxMatchSize) {
                    maxMatchSize = matchSize;
                    // Count for this choice:
                    // For child u (matched): only f0[u] is used, count = f0[u][1]
                    // For other children: product of their best counts
                    long ways = f0[u][1];
                    for (int k = 0; k < children.size(); k++) {
                        if (k == j) continue;
                        ways = (ways * childBestCount[k]) % MOD;
                    }
                    totalWays = ways;
                } else if (matchSize == maxMatchSize) {
                    long ways = f0[u][1];
                    for (int k = 0; k < children.size(); k++) {
                        if (k == j) continue;
                        ways = (ways * childBestCount[k]) % MOD;
                    }
                    totalWays = (totalWays + ways) % MOD;
                }
            }

            if (children.isEmpty()) {
                f1[v][0] = -1; // No child to match with
                f1[v][1] = 0;
            } else {
                f1[v][0] = maxMatchSize;
                f1[v][1] = totalWays;
            }
        }

        // The answer is the number of ways for the root (node 0) such that the maximum matching is unique.
        // The root has no parent, so we can be in state 0 or state 1.
        // We need the maximum matching size, and the count of ways to achieve it with uniqueness.

        long ansSize = Math.max(f0[0][0], f1[0][0]);
        long ansCount = 0;

        if (f0[0][0] == ansSize) {
            ansCount = (ansCount + f0[0][1]) % MOD;
        }
        if (f1[0][0] == ansSize) {
            ansCount = (ansCount + f1[0][1]) % MOD;
        }

        System.out.println(ansCount % MOD);
    }
}
