import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;
    static int n;
    static List<Integer>[] adj;
    static long[] dp0, dp1; // dp0[u] = ways where u is not matched in max matching (unique), dp1[u] = ways where u is matched in max matching (unique)
    static boolean[] visited;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            adj[u].add(v);
            adj[v].add(u);
        }

        dp0 = new long[n + 1];
        dp1 = new long[n + 1];
        visited = new boolean[n + 1];

        dfs(1, 0);

        // The answer is the sum of dp0[1] and dp1[1]
        long ans = (dp0[1] + dp1[1]) % MOD;
        System.out.println(ans);
    }

    static void dfs(int u, int parent) {
        visited[u] = true;

        // dp0[u]: u is not matched in the unique maximum matching
        // dp1[u]: u is matched in the unique maximum matching

        // For dp0[u]: u is free. Each child subtree must have a unique max matching.
        // The child can be in state 0 (free) or state 1 (matched).
