        // So the subtree rooted at v must have a unique max matching, and v can be either free or matched.
        // However, we need to be careful. Let's think about the structure.

        // Actually, let's define:
        // dp0[u]: number of ways to delete edges in subtree of u such that the max matching is unique AND u is NOT matched in that max matching.
        // dp1[u]: number of ways to delete edges in subtree of u such that the max matching is unique AND u IS matched in that max matching.

        // If u is not matched (dp0[u]):
        // For each child v, the edge (u,v) is not selected.
        // The subtree of v must have a unique max matching.
        // v can be either free (dp0[v]) or matched (dp1[v]).
        // So dp0[u] = product over children v of (dp0[v] + dp1[v])

        // If u is matched (dp1[u]):
        // u must be matched to exactly one child v.
        // For the chosen child v:
        //   - The edge (u,v) is selected.
        //   - In the subtree of v, v must be free (so that it can be matched to u). So we use dp0[v].
        //   - The max matching of the subtree of v (with v free) must be unique.
        // For other children w (w != v):
        //   - The edge (u,w) is not selected.
        //   - The subtree of w must have a unique max matching.
        //   - w can be either free or matched. So (dp0[w] + dp1[w]).
        // So dp1[u] = sum over children v of [ dp0[v] * product over w != v of (dp0[w] + dp1[w]) ]

        long prod = 1;
        int childCount = 0;
        for (int v : adj[u]) {
            if (v == parent) continue;
            childCount++;
            dfs(v, u);
            long sum = (dp0[v] + dp1[v]) % MOD;
            prod = (prod * sum) % MOD;
        }

        dp0[u] = prod;

        // Calculate dp1[u]
        // dp1[u] = sum over children v of [ dp0[v] * (prod / (dp0[v] + dp1[v])) ]
        // To avoid division, we can compute prefix and suffix products, or just iterate.
        // Since n can be up to 3e5, and sum of degrees is 2*(n-1), we can do it in O(degree) per node.

        long dp1_u = 0;
        for (int v : adj[u]) {
            if (v == parent) continue;
            long sum_v = (dp0[v] + dp1[v]) % MOD;
            if (sum_v == 0) {
