            term = (term * prod) % MOD;
            dp1_u = (dp1_u + term) % MOD;
        }
        dp1[u] = dp1_u;
    }

    static long modInverse(long a, int mod) {
        return pow(a, mod - 2, mod);
    }

    static long pow(long base, long exp, int mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
