import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;
    static int n;
    static List<Integer>[] adj;
    static long[] dp0, dp1;
    static boolean[] visited;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            String[] parts = br.readLine().split(" ");
            int u = Integer.parseInt(parts[0]);
            int v = Integer.parseInt(parts[1]);
            adj[u].add(v);
            adj[v].add(u);
        }

        dp0 = new long[n + 1];
        dp1 = new long[n + 1];
        visited = new boolean[n + 1];

        dfs(1, 0);

        // The answer is the sum of dp0[1] and dp1[1]
        long ans = (dp0[1] + dp1[1]) % MOD;
        System.out.println(ans);
    }

    static void dfs(int u, int parent) {
        visited[u] = true;
        // dp0[u]: number of ways such that the max matching in subtree rooted at u is unique,
        //         and u is NOT matched to any child (i.e., u is free)
        // dp1[u]: number of ways such that the max matching in subtree rooted at u is unique,
        //         and u IS matched to exactly one child

        // For dp0: u is free. For each child v, we can either:
        //   - not use edge (u,v): then in subtree v, the max matching must be unique.
        //     Both states of v are allowed: v free (dp0[v]) or v matched to its child (dp1[v]).
        //   - use edge (u,v): but u is free, so we cannot use any edge incident to u.
        // So for each child, we just multiply by (dp0[v] + dp1[v]).
        // Wait, that's not quite right. Let me reconsider.

        // Actually, let's define:
        // dp0[u]: number of valid edge subsets in the subtree of u (including edges from u to children)
        //         such that the maximum matching of the induced subgraph on the subtree is unique,
        //         AND u is not matched to any of its children in that maximum matching.
        // dp1[u]: number of valid edge subsets in the subtree of u
        //         such that the maximum matching of the induced subgraph on the subtree is unique,
        //         AND u is matched to exactly one of its children in that maximum matching.

        // For dp0[u]: u is free. For each child v, we consider the edge (u,v).
        //   Option 1: Keep edge (u,v). But since u is free in the max matching, edge (u,v) is not used in the max matching.
        //             However, the subtree of v must still have a unique max matching.
        //             In the subtree of v, v can be free (dp0[v]) or matched to one of its children (dp1[v]).
        //             So contribution from v is (dp0[v] + dp1[v]).
        //   Option 2: Remove edge (u,v). Then the subtree of v is independent.
        //             The max matching in subtree v must be unique: (dp0[v] + dp1[v]).
        //   Wait, if we keep or remove the edge, the condition on the subtree v is the same?
        //   No. If we keep edge (u,v), then in the combined graph, u is free, so edge (u,v) is not in the max matching.
        //   The max matching of the whole subtree is the union of max matchings of each child's subtree.
        //   For uniqueness, each child's subtree must have a unique max matching.
        //   So whether we keep or remove edge (u,v), the contribution from child v is (dp0[v] + dp1[v]).
        //   But wait, if we keep edge (u,v), does it affect the matching in v's subtree? No, because u is free.
        //   So for dp0[u], for each child v, we have 2 choices (keep or remove edge), and for each choice,
        //   the subtree v must have a unique max matching: (dp0[v] + dp1[v]).
        //   So dp0[u] = product over children v of 2 * (dp0[v] + dp1[v])? 
        //   No, that's not right either. Let me think again.

        // Let me redefine more carefully.
        // Let f(u) be the number of ways to choose edges in the subtree of u (edges connecting u to its children, and all edges below)
        // such that the maximum matching of the resulting graph (subtree) is unique.
        // We split into two cases based on whether u is matched in the max matching.

        // dp0[u]: u is NOT matched in the max matching of the subtree.
        //   For each child v, the edge (u,v) may or may not be present.
        //   If edge (u,v) is present, since u is not matched, the edge (u,v) is not used in the max matching.
        //   The max matching of the subtree is the union of max matchings of all child subtrees.
        //   For the overall max matching to be unique, each child subtree must have a unique max matching.
        //   So for each child v, regardless of whether edge (u,v) is kept or removed,
        //   we need the subtree v to have a unique max matching: (dp0[v] + dp1[v]).
        //   And we have 2 choices for the edge (keep or remove).
        //   So dp0[u] = product over children v of 2 * (dp0[v] + dp1[v]).

