        int m = children.size();
        long[] prefix = new long[m + 1];
        long[] suffix = new long[m + 1];
        prefix[0] = 1;
        suffix[m] = 1;

        for (int i = 0; i < m; i++) {
            int v = children.get(i);
            long val = 2 * ((dp0[v] + dp1[v]) % MOD) % MOD;
            prefix[i + 1] = prefix[i] * val % MOD;
        }
        for (int i = m - 1; i >= 0; i--) {
            int v = children.get(i);
            long val = 2 * ((dp0[v] + dp1[v]) % MOD) % MOD;
            suffix[i] = suffix[i + 1] * val % MOD;
        }

        long sum = 0;
        for (int i = 0; i < m; i++) {
            int v = children.get(i);
            long withoutV = prefix[i] * suffix[i + 1] % MOD;
            sum = (sum + dp0[v] * withoutV) % MOD;
        }
        dp1[u] = sum;
    }
}
